 if(kind===4){let current=p.start;const tape=s.data.map(i=>{const prev=current;current=operate(current,p.ops[i]);return `<span>${prev} ${opLabel(p.ops[i])} <b>→ ${current}</b></span>`;});return `<div class="machine"><div><span>START</span><strong>${p.start}</strong></div><span class="machine-arrow">→</span><div class="current-number"><span>NOW</span><strong>${current}</strong></div><span class="machine-arrow">→</span><div><span>TARGET</span><strong>${p.target}</strong></div></div><div class="keys">${p.ops.map((op,i)=>`<button class="operation ${s.data.includes(i)?'used':''}" data-op="${i}" ${s.data.includes(i)?'disabled':''}><strong>${opLabel(op)}</strong><small>${opDetail(op)}</small></button>`).join('')}</div><div class="tape">${tape.length?tape.join(''):'Your calculation tape appears here.'}</div>${s.data.length===6&&current!==p.target?'<p class="warning">All six keys used. Undo to change the order.</p>':''}`;}
