function opLabel(op){return op.type==='add'?`+ ${op.n}`:op.type==='sub'?`− ${op.n}`:op.type==='mul'?`× ${op.n}`:op.type==='half'?'÷ 2':op.type==='reverse'?'Reverse':'100 − n';}
function opDetail(op){return op.type==='reverse'?'Two digits only':op.type==='half'?'Even numbers only':op.type==='mirror'?'Mirror around 50':'Use once';}
function shapeSVG(a,color){return `<svg viewBox="0 0 84 84" aria-hidden="true">${a.map(([x,y])=>`<rect x="${x*19+4}" y="${y*19+4}" width="17" height="17" rx="3" fill="${color}"/>`).join('')}<circle cx="${a[0][0]*19+12.5}" cy="${a[0][1]*19+12.5}" r="3.5" fill="#062334" stroke="white" stroke-width="1.5"/></svg>`;}
function clueText(c){const card=i=>`<b>${String.fromCharCode(65+i)}</b> (${p.values[i]})`;if(c.type==='sum')return `Positions ${Array.from({length:c.len},(_,i)=>c.s+i+1).join(' + ')} add to <b>${c.value}</b>.`;if(c.type==='before')return `${card(c.a)} comes before ${card(c.b)}.`;if(c.type==='gap')return `${card(c.a)} and ${card(c.b)} are <b>${c.gap}</b> position${c.gap===1?'':'s'} apart.`;return `Position <b>${c.a+1}</b> is heavier than position <b>${c.b+1}</b>.`;}
