function studyPanel(){let rows=[];if(kind===1){let at=[...p.start];rows=p.solution.map((d,i)=>{at=twinMove(p,at,d);return `${i+1}. ${['↑ Up','→ Right','↓ Down','← Left'][d]} → A ${coordinate(at[0],4)}; B ${coordinate(at[1],4)}`;});}if(kind===2)rows=p.solution.map((v,i)=>`Strip ${String.fromCharCode(65+i)}: left anchor at beat ${v+1}`);if(kind===3)rows=p.solution.map(([a,b],i)=>`${i+1}. Swap anchors ${a+1} and ${b+1}`);if(kind===4){let value=p.start;rows=p.solution.map((i,j)=>{const before=value;value=operate(value,p.ops[i]);return `${j+1}. ${before} ${opLabel(p.ops[i])} → ${value}`;});}if(kind===5)rows=p.solution.map(o=>`Piece ${String.fromCharCode(65+o.piece)}: orientation ${o.orientation+1}, anchor ${coordinate(o.anchor,5)}`);if(kind===6)rows=[p.solution.map(i=>`${String.fromCharCode(65+i)} (${p.values[i]})`).join(' → ')];if(kind===7)rows=p.solution.map((c,i)=>`Pulse ${i+1}: ${coordinate(c,4)}`);if(kind===8)rows=p.solution.map((v,i)=>`Target ${i+1}: ${v.angle}°, power ${v.power}`);if(kind===9)rows=p.solution.map((v,i)=>`${i+1}. ${i%2?'Rival':'You'} draft card ${v+1}`);if(kind===10)rows=[p.solution.map(v=>v==='F'?'Forward':v==='L'?'Left':'Right').join(' → '),'Repeat this program three times.'];return `<section id="study-panel" class="study-panel" tabindex="-1"><h2>Solution from the starting board</h2><p>${s.firstOutcome?'Your first result is retained.':'This attempt is marked assisted.'}</p><ol>${rows.map(v=>`<li>${esc(v)}</li>`).join('')}</ol></section>`;}
function imageBlob(){return new Promise(resolve=>{const c=document.createElement('canvas');c.width=1080;c.height=1350;const g=c.getContext('2d');g.fillStyle='#08151f';g.fillRect(0,0,1080,1350);const grad=g.createLinearGradient(0,0,1080,1350);grad.addColorStop(0,'#153b53');grad.addColorStop(1,'#08151f');g.fillStyle=grad;g.fillRect(45,45,990,1260);g.fillStyle='#67dfff';g.font='bold 32px sans-serif';g.fillText('ALFORD DAILY · EXPERIMENTAL',100,130);g.fillStyle='#f4fbff';g.font='bold 80px sans-serif';g.fillText(`Candidate ${String(kind).padStart(2,'0')}`,100,260);g.font='36px sans-serif';g.fillStyle='#bad2df';g.fillText(edition(),100,330);const text=shareText(kind,edition(),s).split('\n');g.font='bold 56px sans-serif';g.fillStyle='#66e7c3';g.fillText(text[2],100,660);g.font='38px sans-serif';g.fillStyle='#f4fbff';g.fillText(text[3],100,740);g.fillText(text[4],100,805);for(let i=0;i<10;i++){g.fillStyle=i+1===kind?'#63dfff':'#224253';g.beginPath();if(typeof g.roundRect==='function')g.roundRect(100+i*86,445,64,64,12);else g.rect(100+i*86,445,64,64);g.fill();}g.font='32px sans-serif';g.fillStyle='#bad2df';g.fillText('Same challenge. Your own result.',100,1110);g.font='28px sans-serif';g.fillText('No spoilers. Human keeper verdict pending.',100,1170);c.toBlob(resolve,'image/png');});}
async function shareAction(action){const status=$('#share-status'),text=shareText(kind,edition(),s);if(action==='copy'){try{await navigator.clipboard.writeText(text);status.textContent='Result text copied.';}catch{$('#share-text').focus();$('#share-text').select();status.textContent='Clipboard access is unavailable here. The result is selected; use Copy.';}}if(action==='native-share'){if(!navigator.share){status.textContent='System sharing is unavailable here. Copy text or download the image.';return;}try{await navigator.share({title:`Alford Daily Candidate ${kind}`,text});status.textContent='Shared through your selected app.';}catch{status.textContent='Sharing closed. Your result stays here.';}}if(action==='image'){const blob=await imageBlob().catch(()=>null);if(!blob){status.textContent='Image creation failed. Your text result is still available.';return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`MAKER-Codex__candidate-${String(kind).padStart(2,'0')}-${practice?'practice-'+(practiceIndex+1):BANK.dates[index]}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);status.textContent='PNG download started. It includes only edition, status and attempt totals.';}}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b||b.disabled)return;if(b.dataset.open){openGame(Number(b.dataset.open));return;}if(b.dataset.wave){const[i,to]=b.dataset.wave.split(':').map(Number);waveShift(i,to);return;}if(b.dataset.node!==undefined){selectSwap(Number(b.dataset.node),'node');return;}if(b.dataset.artifact!==undefined){selectSwap(Number(b.dataset.artifact),'artifact');return;}if(b.dataset.op!==undefined){if(s.status!=='playing')return;const i=Number(b.dataset.op),current=s.data.reduce((n,j)=>operate(n,p.ops[j]),p.start),next=operate(current,p.ops[i]);if(next===null){notify('That key cannot be used at this value. No move was spent.');return;}commit(n=>{n.data.push(i);if(n.data.length===6&&next===p.target)done(n);});notify(s.status==='won'?'Every key used. Exact target reached.':`Now ${next}. ${6-s.data.length} keys remain.`);return;}if(b.dataset.piece!==undefined){selected=Number(b.dataset.piece);orientation=0;render();notify(`Piece ${String.fromCharCode(65+selected)} selected. Choose an orientation and position.`);return;}if(b.dataset.cell!==undefined){if(kind===5)putPiece(Number(b.dataset.cell));if(kind===7)pulse(Number(b.dataset.cell));return;}if(b.dataset.draft!==undefined){draft(Number(b.dataset.draft));return;}if(b.dataset.command){chosenCommand=b.dataset.command;render();return;}if(b.dataset.slot!==undefined){if(s.status==='won'){notify('Undo or reset to edit this completed program.');return;}const i=Number(b.dataset.slot);if(s.data[i]===chosenCommand)return;commit(n=>{n.data[i]=chosenCommand;n.lastRun=null;});notify(`Command ${i+1} set to ${chosenCommand==='F'?'Forward':chosenCommand==='L'?'Left':'Right'}.`);return;}const action=b.dataset.action;if(action==='home'){e.preventDefault();stopAnimation();kind=0;lastToast='';render();window.scrollTo({top:0,behavior:'instant'});return;}if(action==='undo'){undo();return;}if(action==='reset'){reset();return;}if(action==='replay'){practiceIndex=practice?(practiceIndex+1)%PRACTICE.games[kind].length:lastPractice()??0;practice=true;lastToast='';load();rememberPractice();render();return;}if(action==='today'){openGame(kind);return;}if(action==='resume-practice'){const saved=lastPractice();if(saved===null)return;practiceIndex=saved;practice=true;lastToast='';load();render();return;}if(action==='share'){$('#share-dialog').showModal();return;}if(action==='close-share'){$('#share-dialog').close();return;}if(['copy','native-share','image'].includes(action)){shareAction(action);return;}if(action==='solution'){$('#study-dialog').showModal();return;}if(action==='cancel-study'){$('#study-dialog').close();return;}if(action==='confirm-study'){$('#study-dialog').close();study();return;}if(action==='next-target'){if(s.status!=='playing'||!s.data.awaitingNext)return;commit(n=>{n.data.awaitingNext=false;},{moves:0});notify('Next target ready.');return;}if(action?.startsWith('dir')){moveDirection(Number(action.slice(3)));return;}if(action?.startsWith('shift')){const[i,d]=action.slice(5).split(':').map(Number);waveShift(i,s.data[i]+d);return;}if(action?.startsWith('orient')){orientation=(orientation+Number(action.slice(6))+orientations(p.shapes[selected]).length)%orientations(p.shapes[selected]).length;render();return;}if(action==='check-order'){if(s.status!=='playing')return;commit(n=>{n.checks++;n.lastCheck=true;if(p.clues.every(c=>cluePass(p,n.data,c)))done(n);},{moves:0});notify(s.status==='won'?'Every clue agrees.':`${p.clues.filter(c=>cluePass(p,s.data,c)).length} of ${p.clues.length} clues agree. Keep deducing.`);return;}if(action==='launch'){launch();return;}if(action==='run'){if(s.status!=='playing')return;commit(n=>{n.lastRun=runProgram(p,n.data);if(n.lastRun.won)done(n);});notify(s.lastRun.won?'Three loops, three beacons, exact arrival.':s.lastRun.crashed?`Blocked in loop ${s.lastRun.cycle+1}, command ${s.lastRun.slot+1}.`:'Run finished. Check beacons, goal and facing.');}});
function rangeInput(e){if(e.target.id==='angle'||e.target.id==='power'){if(kind!==8||s.status!=='playing'||s.data.awaitingNext)return;const name=e.target.id,value=Number(e.target.value);if(!Number.isInteger(value))return;s.data[name]=value;const readout=$(`[data-readout="${name}"]`);if(readout)readout.textContent=value+(name==='angle'?'°':'');store();}if(e.target.id==='run-step'&&kind===10&&s.lastRun){runStep=Math.max(0,Math.min(s.lastRun.steps.length,Number(e.target.value)||0));const temp=document.createElement('div');temp.innerHTML=board();$('.program-map').replaceWith(temp.querySelector('.program-map'));$('.run-review strong').textContent=temp.querySelector('.run-review strong').textContent;}}
document.addEventListener('input',rangeInput);
document.addEventListener('change',e=>{if(['angle','power','run-step'].includes(e.target.id)){rangeInput(e);return;}if(e.target.id==='date'){currentDay=chicagoDate();const i=BANK.dates.indexOf(e.target.value);if(i<0||e.target.value>currentDay){notify('Choose an available Daily on or before today in Chicago.');e.target.value=BANK.dates[index]||'';return;}index=i;practice=false;lastToast='';load();render();}});
function syncDay(){const day=chicagoDate(),changed=day!==currentDay;currentDay=day;const date=$('#date');if(date)date.max=availableMax();const banner=$('#date-banner');if(banner&&kind&&!practice&&BANK.dates[index]!==currentDay&&BANK.dates.includes(currentDay)){if(!banner.querySelector('[data-action="today"]'))banner.innerHTML=`Today’s Daily is available. Your current edition is retained. ${control('Open today','today','class="quiet"')}`;}else if(banner&&banner.childNodes.length)banner.textContent='';if(changed)notify('A new Chicago Daily date is available. Your open board is retained.');}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncDay();});window.addEventListener('focus',syncDay);setInterval(syncDay,30000);
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.isComposing||e.keyCode===229||e.target.isContentEditable||e.target.closest?.('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"]'))return;if(!p||s.status!=='playing'||$('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(kind===4&&/^[1-6]$/.test(e.key)){e.preventDefault();$(`[data-op="${Number(e.key)-1}"]`)?.click();return;}if(kind===10&&/^[flr]$/i.test(e.key)){e.preventDefault();$(`[data-command="${e.key.toUpperCase()}"]`)?.click();return;}if(kind===10&&/^[1-6]$/.test(e.key)){e.preventDefault();$(`[data-slot="${Number(e.key)-1}"]`)?.click();return;}if(kind===1&&!$('#share-dialog')?.open&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].includes(e.key)){e.preventDefault();moveDirection(['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].indexOf(e.key));}});
// QA can inspect state without reading hidden solutions. No action is auto-played.
window.candidateLab={snapshot:()=>({kind,index:practice?practiceIndex:index,practice,date:practice?null:BANK.dates[index],state:copy(s),historyLength:history.length}),open:openGame};
render();
